begin;

drop table if exists _calfix_levels;
create temp table _calfix_levels (start_date, end_date, label, levels) as
values
  (date '2026-02-25', date '2026-02-27', 'Secondary School Term 1 Exam', array['S1', 'S2', 'S3', 'S4']::text[]),
  (date '2026-02-27', date '2026-02-27', 'Primary One Fieldtrip', array['P1']::text[]),
