  (date '2026-03-12', date '2026-03-12', 'Primary Four Fieldtrip', array['P4']::text[]),
  (date '2026-04-17', date '2026-04-17', 'Primary Two and Three Fieldtrip', array['P2', 'P3']::text[]),
